static unsigned job_steps;
static int complete(IEJob*j){int result=0;unsigned limit=100000;CHECK(j);while(!result&&limit--){result=ie_job_step(j,37);++job_steps;}CHECK(limit);ie_job_destroy(j);return result;}
static unsigned selected(IEDoc*d){unsigned n=0;for(int y=0;y<d->current.height;y++)for(int x=0;x<d->current.width;x++)n+=ie_selection_alpha(&d->current,x,y)>0;return n;}
static IESelectionOptions rectangle(int x,int y,int xx,int yy){IESelectionOptions q={0};q.x0=x;q.y0=y;q.x1=xx;q.y1=yy;return q;}
static IEFillOptions fill_defaults(void){IEFillOptions q={0};q.kind=IE_FILL_SOLID;q.region=IE_FILL_SELECTION;q.opacity=q.density=100;q.scale=4;q.foreground=IE_RGBA(210,30,40,255);q.background=IE_RGBA(30,60,210,255);return q;}
static void selections(void){IEDoc d;Memory m;IESelectionOptions q;setup(&d,&m,17,13);q=rectangle(2,3,10,9);CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==63);CHECK(d.current.selection.x==2&&d.current.selection.w==9);q=rectangle(5,5,7,7);q.combine=IE_SELECT_SUBTRACT;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==54);CHECK(!ie_selection_alpha(&d.current,6,6));q.combine=IE_SELECT_ADD;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==63);q.combine=IE_SELECT_INTERSECT;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==9);q.method=IE_SELECT_INVERT;q.combine=0;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==17*13-9);
 q=rectangle(2,2,12,10);q.method=IE_SELECT_ELLIPSE;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(ie_selection_alpha(&d.current,7,6)==255);CHECK(ie_selection_alpha(&d.current,2,2)==0);for(int y=2;y<=10;y++)for(int x=2;x<=12;x++)CHECK(ie_selection_alpha(&d.current,x,y)==ie_selection_alpha(&d.current,14-x,12-y));
 IEPoint points[]={{2,2},{12,2},{12,10},{7,6},{2,10}};q.method=IE_SELECT_LASSO;q.points=points;q.point_count=5;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(ie_selection_alpha(&d.current,3,3)==255);CHECK(ie_selection_alpha(&d.current,7,9)==0);CHECK(ie_selection_alpha(&d.current,1,2)==0);CHECK(selected(&d)>40&&selected(&d)<90);IEPoint boundary[]={{0,0},{16,0},{16,12},{0,12}};q.points=boundary;q.point_count=4;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==17*13);IEPoint zigzag[2048];for(int i=0;i<2048;i++){zigzag[i].x=(i*7)%17;zigzag[i].y=i&1?12:0;}q.points=zigzag;q.point_count=2048;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)>0);
 q=rectangle(2,2,6,6);q.combine=IE_SELECT_INTERSECT;ie_select(&d,10,10,12,12);CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(d.current.selection.enabled&&selected(&d)==0);uint64_t before=digest(&d);IEFillOptions f=fill_defaults();CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(digest(&d)==before&&d.undo_count==0);cleanup(&d,&m);
}
static void feather(void){IEDoc d;Memory m;setup(&d,&m,13,11);for(int radius=1;radius<=6;radius++){IESelectionOptions q=rectangle(0,2,8,8);q.feather=radius;CHECK(complete(ie_selection_start(&d,&q))==1);int k=2*radius+1;for(int y=0;y<11;y++)for(int x=0;x<13;x++){unsigned vertical=0;for(int yy=y-radius;yy<=y+radius;yy++){unsigned horizontal=0;int cy=yy<0?0:yy>10?10:yy;for(int xx=x-radius;xx<=x+radius;xx++){int cx=xx<0?0:xx>12?12:xx;horizontal+=(cx<=8&&cy>=2&&cy<=8)?255:0;}vertical+=(horizontal+k/2)/k;}CHECK(ie_selection_alpha(&d.current,x,y)==(vertical+k/2)/k);}}
 uint8_t mask[13*11];memcpy(mask,d.current.selection_mask,sizeof mask);uint64_t before=digest(&d);CHECK(ie_clear(&d));for(int y=0;y<11;y++)for(int x=0;x<13;x++)CHECK((ie_composite(&d,x,y)>>24)==255u-mask[y*13+x]);CHECK(ie_undo(&d));CHECK(digest(&d)==before&&!memcmp(mask,d.current.selection_mask,sizeof mask));CHECK(ie_redo(&d));CHECK(!memcmp(mask,d.current.selection_mask,sizeof mask));CHECK(ie_undo(&d));CHECK(ie_transform(&d,100,100,0,0));CHECK(digest(&d)==before);CHECK(ie_undo(&d));CHECK(!memcmp(mask,d.current.selection_mask,sizeof mask));cleanup(&d,&m);}
static void floods(void){IEDoc d;Memory m;setup(&d,&m,9,7);for(int y=0;y<7;y++)d.current.layers[0].pixels[y*9+4]=0xff000000;IESelectionOptions q=rectangle(0,0,0,0);q.method=IE_SELECT_CONTIGUOUS;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==28);q.method=IE_SELECT_COLOR;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==56);q.method=IE_SELECT_CONTIGUOUS;q.tolerance=255;q.edge=40;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==28);q.edge=0;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(selected(&d)==63);
 /* Random binary maps compared to an independent fixed-point reachability oracle. */
 unsigned state=817;for(int cycle=0;cycle<150;cycle++){unsigned char expected[63]={0};for(int i=0;i<63;i++){state=state*1664525u+1013904223u;d.current.layers[0].pixels[i]=state>>31?0xff000000:0xffffffff;}q.tolerance=0;q.x0=cycle%9;q.y0=cycle%7;expected[q.y0*9+q.x0]=1;int changed;do{changed=0;for(int y=0;y<7;y++)for(int x=0;x<9;x++){int i=y*9+x;if(!expected[i]&&d.current.layers[0].pixels[i]==d.current.layers[0].pixels[q.y0*9+q.x0]&&((x&&expected[i-1])||(x<8&&expected[i+1])||(y&&expected[i-9])||(y<6&&expected[i+9]))){expected[i]=1;changed=1;}}}while(changed);CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<63;i++)CHECK(!!ie_selection_alpha(&d.current,i%9,i/9)==expected[i]);}
 cleanup(&d,&m);
}
static void fills(void){IEDoc d;Memory m;setup(&d,&m,24,20);IEFillOptions f=fill_defaults();IESelectionOptions q=rectangle(4,4,17,15);q.method=IE_SELECT_ELLIPSE;q.feather=2;CHECK(complete(ie_selection_start(&d,&q))==1);uint8_t mask[480];memcpy(mask,d.current.selection_mask,sizeof mask);CHECK(ie_layer_add(&d,"Fill"));uint64_t empty=digest(&d);for(int kind=0;kind<=IE_FILL_DOTS;kind++){f.kind=kind;f.x=10;f.y=10;f.opacity=50;f.density=65;unsigned count=d.undo_count;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(d.undo_count==count+1);CHECK(digest(&d)!=empty);for(int i=0;i<480;i++){CHECK(d.current.layers[0].pixels[i]==0xffffffff);CHECK((d.current.layers[1].pixels[i]>>24)<=(mask[i]*50u+50)/100);if(!mask[i])CHECK(!d.current.layers[1].pixels[i]);}CHECK(ie_undo(&d));CHECK(digest(&d)==empty&&!memcmp(mask,d.current.selection_mask,sizeof mask));CHECK(ie_redo(&d));CHECK(ie_undo(&d));}
 ie_deselect(&d);f=fill_defaults();f.kind=IE_FILL_LINEAR;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(d.current.layers[1].pixels[0]==f.foreground&&d.current.layers[1].pixels[23]==f.background);CHECK(ie_undo(&d));f.kind=IE_FILL_SOLID;f.region=IE_FILL_CONTIGUOUS;f.sample_merged=0;ie_select(&d,3,3,9,9);CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(digest(&d)==empty);f.x=5;f.y=5;CHECK(complete(ie_fill_start(&d,&f))==1);CHECK(d.current.layers[1].pixels[5*24+5]==f.foreground);CHECK(d.current.layers[1].pixels[0]==0);cleanup(&d,&m);
}
static void rollback_and_oom(void){for(int sign=-1;sign<=1;sign+=2)for(int type=0;type<3;type++)for(int failure=0;failure<12;failure++){IEDoc d;Memory m;setup(&d,&m,32,24);IESelectionOptions q=rectangle(4,4,20,18);q.feather=sign*3;CHECK(complete(ie_selection_start(&d,&q))==1);uint8_t mask[768];memcpy(mask,d.current.selection_mask,sizeof mask);uint64_t before=digest(&d);size_t live=m.live;IEPoint points[]={{2,2},{28,4},{17,20}};q.method=type==0?IE_SELECT_CONTIGUOUS:IE_SELECT_LASSO;q.points=points;q.point_count=3;IEFillOptions f=fill_defaults();f.region=IE_FILL_CONTIGUOUS;f.feather=sign*3;f.x=9;f.y=9;m.fail_at=m.calls+failure;m.persistent=1;IEJob*j=type==2?ie_fill_start(&d,&f):ie_selection_start(&d,&q);if(j){int result=0;while(!result)result=ie_job_step(j,37);if(result<0){CHECK(digest(&d)==before);CHECK(!memcmp(mask,d.current.selection_mask,sizeof mask));}ie_job_destroy(j);}else{CHECK(digest(&d)==before&&!memcmp(mask,d.current.selection_mask,sizeof mask));CHECK(m.live==live);}m.fail_at=-1;cleanup(&d,&m);}
 IEDoc d;Memory m;setup(&d,&m,80,60);CHECK(ie_adjust(&d,-20,0,0,100,100,100,0));CHECK(ie_undo(&d));d.dirty=0;uint64_t before=digest(&d);unsigned undo=d.undo_count,redo=d.redo_count;IEFillOptions f=fill_defaults();IEJob*j=ie_fill_start(&d,&f);CHECK(j);unsigned iterations=0;while(digest(&d)==before){CHECK(!ie_job_step(j,80));CHECK(++iterations<1000);}CHECK(d.gesture);ie_job_cancel(j);CHECK(digest(&d)==before&&d.undo_count==undo&&d.redo_count==redo&&!d.dirty);ie_job_destroy(j);CHECK(ie_redo(&d));cleanup(&d,&m);
 /* Reject a masked snapshot exceeding the explicit history cap before mutation. */
 setup(&d,&m,1800,1000);IESelectionOptions q=rectangle(1,1,1700,900);before=digest(&d);CHECK(!ie_selection_start(&d,&q));CHECK(digest(&d)==before&&!d.current.selection_mask&&d.history_bytes<=IE_HISTORY_MAX_BYTES);cleanup(&d,&m);setup(&d,&m,1000,1000);q=rectangle(2,2,900,900);CHECK(complete(ie_selection_start(&d,&q))==1);before=digest(&d);CHECK(!ie_layer_add(&d,"Too large with mask"));CHECK(digest(&d)==before&&d.current.count==1&&d.current.selection_mask);cleanup(&d,&m);
}
static void masked_move(void){IEDoc d;Memory m;setup(&d,&m,12,10);CHECK(ie_new(&d,12,10,0));d.current.layers[0].pixels[4*12+4]=0xff123456;IESelectionOptions q=rectangle(3,3,6,6);q.method=IE_SELECT_ELLIPSE;CHECK(complete(ie_selection_start(&d,&q))==1);uint64_t before=digest(&d);CHECK(ie_translate_selection(&d,3,2));CHECK(d.current.layers[0].pixels[6*12+7]==0xff123456);CHECK(d.current.layers[0].pixels[4*12+4]==0);CHECK(ie_undo(&d));CHECK(digest(&d)==before);uint16_t out[40];ie_render_selection_outline(&d,out,8,8,5,0,0,100,INT_MAX,INT_MAX,INT_MAX,INT_MAX);ie_render_selection_outline(&d,out,8,8,5,0,0,100,0,0,8,5);cleanup(&d,&m);}
/* An absent selection is an unrestricted paint canvas, never the operand of an
   implicit inverse. The explicitly enabled empty mask remains a real operand. */
static void first_selection(void){
 IEDoc d;Memory m;setup(&d,&m,23,19);for(int y=0;y<19;y++)d.current.layers[0].pixels[y*23+12]=0xff000000;
 IEPoint polygon[]={{3,3},{18,3},{18,14},{11,9},{3,14}};uint8_t expected[23*19];
 for(int method=IE_SELECT_RECT;method<=IE_SELECT_COLOR;method++)for(int radius=-2;radius<=2;radius+=2){
  IESelectionOptions q=rectangle(3,3,18,14);q.method=method;q.points=polygon;q.point_count=5;q.feather=radius;
  ie_deselect(&d);CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<23*19;i++)expected[i]=(uint8_t)ie_selection_alpha(&d.current,i%23,i/23);
  for(int combine=IE_SELECT_ADD;combine<=IE_SELECT_INTERSECT;combine++){ie_deselect(&d);q.combine=combine;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<23*19;i++)CHECK(expected[i]==ie_selection_alpha(&d.current,i%23,i/23));}
 }
 ie_select(&d,1,1,2,2);IESelectionOptions q=rectangle(10,10,13,13);q.combine=IE_SELECT_INTERSECT;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(d.current.selection.enabled&&!selected(&d));q.combine=IE_SELECT_SUBTRACT;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(d.current.selection.enabled&&!selected(&d));cleanup(&d,&m);
}
static unsigned blur_oracle(const uint8_t*source,int w,int h,int x,int y,int radius){
 const int k=2*radius+1;unsigned vertical=0;
 for(int yy=y-radius;yy<=y+radius;yy++){const int cy=yy<0?0:yy>=h?h-1:yy;unsigned horizontal=0;for(int xx=x-radius;xx<=x+radius;xx++){const int cx=xx<0?0:xx>=w?w-1:xx;horizontal+=source[cy*w+cx];}vertical+=(horizontal+k/2)/(unsigned)k;}
 return (vertical+k/2)/(unsigned)k;
}
static unsigned support_blur_oracle(const uint8_t*source,int w,int h,int x,int y,int radius){uint8_t support[37*29];CHECK(w*h<=(int)sizeof support);for(int i=0;i<w*h;i++)support[i]=source[i]?255:0;return blur_oracle(support,w,h,x,y,radius);}
static unsigned inner_oracle(unsigned blur,unsigned original){unsigned a=blur<=127?0:2*blur-255;return (a*original+127)/255;}
static void signed_feather(void){
 IEDoc d;Memory m;setup(&d,&m,19,17);IEPoint points[]={{3,2},{15,2},{15,14},{9,8},{3,14}};uint8_t original[19*17];
 for(int method=IE_SELECT_RECT;method<=IE_SELECT_LASSO;method++)for(int radius=1;radius<=8;radius++){
  IESelectionOptions q=rectangle(3,2,15,14);q.method=method;q.points=points;q.point_count=5;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<19*17;i++)original[i]=(uint8_t)ie_selection_alpha(&d.current,i%19,i/19);
  for(int sign=-1;sign<=1;sign+=2){q.feather=sign*radius;CHECK(complete(ie_selection_start(&d,&q))==1);for(int y=0;y<17;y++)for(int x=0;x<19;x++){const unsigned blur=blur_oracle(original,19,17,x,y,radius);unsigned expected=sign>0?blur:inner_oracle(support_blur_oracle(original,19,17,x,y,radius),original[y*19+x]);CHECK(ie_selection_alpha(&d.current,x,y)==expected);if(sign<0)CHECK(expected<=original[y*19+x]);}}
 }
 /* Hole and antialias alpha are preserved as restrictions, including zero. */
 IESelectionOptions q=rectangle(2,2,16,14);q.method=IE_SELECT_ELLIPSE;CHECK(complete(ie_selection_start(&d,&q))==1);q=rectangle(7,6,10,10);q.combine=IE_SELECT_SUBTRACT;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<19*17;i++)original[i]=(uint8_t)ie_selection_alpha(&d.current,i%19,i/19);q=(IESelectionOptions){0};q.method=IE_SELECT_EXISTING;q.feather=-3;CHECK(complete(ie_selection_start(&d,&q))==1);for(int y=0;y<17;y++)for(int x=0;x<19;x++)CHECK(ie_selection_alpha(&d.current,x,y)==inner_oracle(support_blur_oracle(original,19,17,x,y,3),original[y*19+x]));
 q=rectangle(2,2,16,14);CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<19*17;i++)if(d.current.selection_mask[i])d.current.selection_mask[i]=96;q.method=IE_SELECT_EXISTING;q.feather=-2;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(ie_selection_alpha(&d.current,9,8)==96);CHECK(ie_selection_alpha(&d.current,0,0)==0);
 /* Saturate before abs(), including INT_MIN; the existing 32px limit stays. */
 q=rectangle(3,2,15,14);for(int sign=-1;sign<=1;sign+=2){q.feather=sign*32;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<19*17;i++)original[i]=(uint8_t)ie_selection_alpha(&d.current,i%19,i/19);q.feather=sign<0?INT_MIN:INT_MAX;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<19*17;i++)CHECK(ie_selection_alpha(&d.current,i%19,i/19)==original[i]);}
 cleanup(&d,&m);
}
static void lasso_direction(void){
 IEDoc d;Memory m;setup(&d,&m,37,29);const IEPoint shapes[][8]={{{3,3},{30,4},{31,24},{17,13},{4,25}},{{2,2},{33,24},{2,24},{33,2}},{{0,0},{36,0},{36,28},{0,28}},{{8,4},{28,4},{28,22},{8,22}},{{18,2},{21,10},{33,13},{22,16},{18,27},{14,17},{2,13},{13,9}}};const unsigned counts[]={5,4,4,4,8};uint8_t original[37*29];
 for(unsigned shape=0;shape<5;shape++)for(int feather=-3;feather<=3;feather+=3){IEPoint reverse[8];unsigned n=counts[shape];for(unsigned i=0;i<n;i++)reverse[i]=shapes[shape][n-1-i];IESelectionOptions q={0};q.method=IE_SELECT_LASSO;q.points=shapes[shape];q.point_count=n;q.feather=feather;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<37*29;i++)original[i]=(uint8_t)ie_selection_alpha(&d.current,i%37,i/37);q.points=reverse;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<37*29;i++)CHECK(original[i]==ie_selection_alpha(&d.current,i%37,i/37));}
 /* Dragging a rectangle in all four directions identifies the same region. */
 for(int method=IE_SELECT_RECT;method<=IE_SELECT_ELLIPSE;method++)for(int feather=-3;feather<=3;feather+=3){IESelectionOptions q=rectangle(5,4,29,22);q.method=method;q.feather=feather;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<37*29;i++)original[i]=(uint8_t)ie_selection_alpha(&d.current,i%37,i/37);for(int direction=1;direction<4;direction++){q.x0=direction&1?29:5;q.x1=direction&1?5:29;q.y0=direction&2?22:4;q.y1=direction&2?4:22;CHECK(complete(ie_selection_start(&d,&q))==1);for(int i=0;i<37*29;i++)CHECK(original[i]==ie_selection_alpha(&d.current,i%37,i/37));}}
 cleanup(&d,&m);
}
static void signed_fill(void){
 IEDoc d;Memory m;setup(&d,&m,23,19);IESelectionOptions q=rectangle(4,3,18,15);q.method=IE_SELECT_ELLIPSE;q.feather=1;CHECK(complete(ie_selection_start(&d,&q))==1);CHECK(ie_layer_add(&d,"Fill"));uint8_t original[23*19];for(int i=0;i<23*19;i++)original[i]=(uint8_t)ie_selection_alpha(&d.current,i%23,i/23);IEFillOptions f=fill_defaults();
 for(int feather=-4;feather<=4;feather++){f.feather=feather;CHECK(complete(ie_fill_start(&d,&f))==1);for(int y=0;y<19;y++)for(int x=0;x<23;x++){unsigned old=original[y*23+x],blur=feather?blur_oracle(original,23,19,x,y,abs(feather)):old,expected=feather<0?inner_oracle(support_blur_oracle(original,23,19,x,y,-feather),old):blur<old?blur:old;CHECK((d.current.layers[1].pixels[y*23+x]>>24)==expected);CHECK(ie_selection_alpha(&d.current,x,y)==old);}CHECK(ie_undo(&d));}
 /* A matching/contiguous fill can soften inside its discovered boundary even
    with no active selection. Active selection still clips once afterwards. */
 ie_deselect(&d);for(int y=0;y<19;y++)for(int x=0;x<23;x++)d.current.layers[0].pixels[y*23+x]=(x>=4&&x<=18&&y>=3&&y<=15)?0xffffffff:0xff000000;for(int i=0;i<23*19;i++)original[i]=d.current.layers[0].pixels[i]==0xffffffff?255:0;
 for(int region=IE_FILL_CONTIGUOUS;region<=IE_FILL_MATCHING;region++)for(int feather=-4;feather<=4;feather+=4){f.region=region;f.feather=feather;f.sample_merged=1;f.x=10;f.y=9;CHECK(complete(ie_fill_start(&d,&f))==1);for(int y=0;y<19;y++)for(int x=0;x<23;x++){unsigned old=original[y*23+x],blur=feather?blur_oracle(original,23,19,x,y,abs(feather)):old,expected=feather<0?inner_oracle(support_blur_oracle(original,23,19,x,y,-feather),old):blur;CHECK((d.current.layers[1].pixels[y*23+x]>>24)==expected);}CHECK(ie_undo(&d));}
 cleanup(&d,&m);
}

int main(void){regression_main();first_selection();signed_feather();lasso_direction();signed_fill();selections();feather();floods();fills();rollback_and_oom();masked_move();printf("{\"checks\":%u,\"jobSteps\":%u,\"peakBytes\":%zu,\"randomFloodCases\":150,\"allocationFaultCases\":72,\"passed\":true}\n",checks,job_steps,peak_bytes);}
